@SpringBootTest(classes = TestApp.class, webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class TestRestTemplateTest {

    @LocalServerPort
    int port;

    @Autowired
    TestRestTemplate testRestTemplate;

    @Test
    void test() {
        Map<String, Object> body = testRestTemplate.getForObject(
                "http://localhost:" + port + "/products/P1", Map.class);
        assertThat(body).containsEntry("id", "P1");
    }
}

@AutoConfigureWebTestClient
class WebTestClientTest {

    @Autowired
    WebTestClient webTestClient;

    @Test
    void test() {
        webTestClient.get().uri("/products/P2")
                .exchange()
                .expectStatus().isOk()
                .expectBody()
                .jsonPath("$.id").isEqualTo("P2")
                .jsonPath("$.name").isEqualTo("Klawiatura");
    }
}

